function queueCardZoomSave(){zoomPending=true;clearTimeout(zoomSaveTimer);zoomSaveTimer=setTimeout(()=>{zoomSaveTimer=null;const target=cardScale();zoomSaveChain=zoomSaveChain.catch(()=>{}).then(()=>api('/settings','POST',{card_scale:target})).then(()=>{zoomPersistedScale=target}).catch(error=>{if(Math.abs(cardScale()-target)<.001){state.settings.card_scale=zoomPersistedScale;updateCardZoomControls();zoomNotice(error?.message||'Could not save card size preference.')}}).finally(()=>{if(!zoomSaveTimer&&Math.abs(cardScale()-target)<.001)zoomPending=false})},180)}
function changeCardZoom(direction){const next=Math.max(.55,Math.min(1.75,Math.round((cardScale()+direction*.15)*100)/100));if(next===cardScale())return;state.settings.card_scale=next;updateCardZoomControls();queueCardZoomSave()}
document.querySelector('#cardZoomOut').addEventListener('click',()=>void changeCardZoom(-1));document.querySelector('#cardZoomIn').addEventListener('click',()=>void changeCardZoom(1));
document.querySelector('#arrangeBtn').onclick=()=>{
  arrangeMode=!arrangeMode;selectedDeviceId=null;const button=document.querySelector('#arrangeBtn');
  button.classList.toggle('arrange-active',arrangeMode);button.setAttribute('aria-pressed',String(arrangeMode));button.textContent=arrangeMode?'Cancel arrange':'Arrange';
  document.querySelector('#pageTitle').textContent=arrangeMode?'Arrange devices':'Network overview';renderGroups();
};
// Subgroups always receive a top-level parent ID from this selector.
window.openGroupForm=group=>{
  editingGroup=group?.id?Number(group.id):null;const form=document.querySelector('#groupForm'),parent=document.querySelector('#parentGroupSelect');
  form.reset();setFormError(form);const roots=state.groups.filter(g=>(g.parent_id==null||Number(g.parent_id)===0)&&Number(g.id)!==editingGroup);
  parent.innerHTML='<option value="">No parent (top-level group)</option>'+roots.map(g=>`<option value="${Number(g.id)}">${escapeHtml(g.name)}</option>`).join('');
  form.elements.name.value=group?.name||'';if(group?.parent_id!=null&&[...parent.options].some(o=>o.value===String(group.parent_id)))parent.value=String(group.parent_id);
  document.querySelector('#groupModalTitle').innerHTML=editingGroup?`${EDIT_ICON}<span>${group?.parent_id?'Edit subgroup':'Edit group'}</span>`:(group?.parent_id?'Add subgroup':'Add group');deleteGroupButton.hidden=!editingGroup;deleteGroupButton.textContent=group?.parent_id?'Delete subgroup':'Delete group';
  document.querySelector('#groupDialog').showModal();form.elements.name.focus();
};
window.renameGroup=id=>window.openGroupForm(state.groups.find(g=>Number(g.id)===Number(id)));document.querySelector('#groupBtn').onclick=()=>window.openGroupForm();

// On-demand report charts are generated only inside this modal; the dashboard remains chart-free.
function localDateTimeValue(date){const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function populateReportDevices(){const select=document.querySelector('#reportDevice'),current=select.value;select.replaceChildren(new Option('All devices','all'));for(const device of state.devices){const ips=(device.ips||[]).join(', '),label=[device.name,device.alias,ips].filter(Boolean).join(' · ');select.add(new Option(label,String(device.id)))}if([...select.options].some(option=>option.value===current))select.value=current}
function reportDuration(seconds){const total=Math.max(0,Math.round(Number(seconds)||0)),days=Math.floor(total/86400),hours=Math.floor(total%86400/3600),minutes=Math.floor(total%3600/60),secs=total%60;return [days?`${days}d`:null,hours?`${hours}h`:null,`${minutes}m`,`${secs}s`].filter(Boolean).join(' ')}
function renderReportChart(report,metrics,start,end,deviceLabel){const canvas=document.querySelector('#reportCanvas'),ctx=canvas.getContext('2d'),width=1400,header=170,panelHeight=270,height=header+panelHeight*metrics.length+30,points=report.series||[],rows=report.rows||[];canvas.width=width;canvas.height=height;ctx.fillStyle='#111827';ctx.fillRect(0,0,width,height);ctx.fillStyle='#f3f4f6';ctx.font='600 30px Inter,system-ui,sans-serif';ctx.fillText('AriYouLive · Device Report',54,55);ctx.fillStyle='#cbd5e1';ctx.font='500 17px Inter,system-ui,sans-serif';ctx.fillText(deviceLabel,56,88);ctx.fillStyle='#9ca3af';ctx.font='14px Inter,system-ui,sans-serif';ctx.fillText(`${new Date(start).toLocaleString()}  —  ${new Date(end).toLocaleString()}   ·   ${rows.length} device${rows.length===1?'':'s'}`,56,119);const totalDown=rows.reduce((sum,row)=>sum+Number(row.down_count||0),0),totalDownSeconds=rows.reduce((sum,row)=>sum+Number(row.downtime_seconds||0),0),sent=rows.reduce((sum,row)=>sum+Number(row.probes_sent||0),0),received=rows.reduce((sum,row)=>sum+Number(row.probes_received||0),0),summary=[metrics.includes('down_count')?`${totalDown} disconnections`:null,metrics.includes('downtime')?`${reportDuration(totalDownSeconds)} downtime`:null,metrics.includes('availability')?`${sent?`${(received/sent*100).toFixed(2)}%`:'No data'} availability`:null].filter(Boolean).join('   ·   ');ctx.fillStyle='#93c5fd';ctx.font='600 14px Inter,system-ui,sans-serif';ctx.fillText(summary,56,148);const metricMeta={availability:{title:'Availability',color:'#10b981',unit:'%'},down_count:{title:'Disconnections',color:'#f97316',unit:'count'},downtime:{title:'Downtime',color:'#ef4444',unit:'seconds'}};metrics.forEach((metric,index)=>{const meta=metricMeta[metric],top=header+index*panelHeight,plotX=104,plotY=top+52,plotW=1240,plotH=155,values=points.map(point=>metric==='availability'?point.availability_percent:metric==='down_count'?Number(point.down_count||0):Number(point.downtime_seconds||0)),hasData=metric==='availability'?rows.some(row=>Number(row.probes_sent)>0):rows.length>0;ctx.fillStyle='#1f2937';ctx.fillRect(40,top,width-80,panelHeight-12);ctx.fillStyle='#e5e7eb';ctx.font='600 18px Inter,system-ui,sans-serif';ctx.fillText(meta.title,plotX,top+31);if(metric==='downtime'){const maximum=Math.max(1,...values),scale=maximum>=3600?3600:maximum>=60?60:1,suffix=scale===3600?'h':scale===60?'m':'s',scaled=values.map(value=>value/scale),max=Math.max(1,...scaled);drawReportPlot(ctx,plotX,plotY,plotW,plotH,scaled,max,meta.color,false,suffix,start,end)}else{const maximum=metric==='availability'?100:Math.max(1,...values),max=metric==='availability'?100:Math.ceil(maximum);drawReportPlot(ctx,plotX,plotY,plotW,plotH,values,max,meta.color,metric==='availability',meta.unit,start,end)}if(!hasData){ctx.fillStyle='#9ca3af';ctx.font='14px Inter,system-ui,sans-serif';ctx.fillText('No history available for this metric in the selected period.',plotX+18,plotY+82)}})}
function drawReportPlot(ctx,x,y,w,h,values,max,color,line,unit,start,end){ctx.strokeStyle='#374151';ctx.lineWidth=1;ctx.fillStyle='#9ca3af';ctx.font='12px Inter,system-ui,sans-serif';for(let tick=0;tick<=4;tick++){const yy=y+h-(h*tick/4);ctx.beginPath();ctx.moveTo(x,yy);ctx.lineTo(x+w,yy);ctx.stroke();const label=(max*tick/4).toFixed(max<=4?1:0);ctx.fillText(`${label}${unit==='%'?'%':''}`,x-46,yy+4)}const slot=w/Math.max(1,values.length);if(line){ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();let started=false;values.forEach((value,index)=>{if(value==null){started=false;return}const px=x+slot*(index+.5),py=y+h-(Math.max(0,Math.min(max,value))/max)*h;if(!started){ctx.moveTo(px,py);started=true}else ctx.lineTo(px,py)});ctx.stroke();values.forEach((value,index)=>{if(value==null)return;const px=x+slot*(index+.5),py=y+h-(Math.max(0,Math.min(max,value))/max)*h;ctx.fillStyle=color;ctx.beginPath();ctx.arc(px,py,3.5,0,Math.PI*2);ctx.fill()})}else{ctx.fillStyle=color;values.forEach((value,index)=>{const amount=Math.max(0,Math.min(max,value||0)),barH=amount/max*h,bw=Math.max(2,slot*.62);ctx.fillRect(x+slot*index+(slot-bw)/2,y+h-barH,bw,barH)})}ctx.fillStyle='#9ca3af';for(let tick=0;tick<=4;tick++){const index=Math.min(values.length-1,Math.round((values.length-1)*tick/4)),date=new Date(start+(end-start)*tick/4);ctx.fillText(date.toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}),x+slot*index-12,y+h+24)}}
document.querySelector('#exportReportBtn').onclick=()=>{populateReportDevices();const now=new Date();document.querySelector('#reportEnd').value=localDateTimeValue(now);document.querySelector('#reportStart').value=localDateTimeValue(new Date(now.getTime()-86400000));document.querySelector('#reportRange').value='24h';document.querySelector('#reportCustomDates').hidden=true;document.querySelector('#reportPreview').hidden=true;document.querySelector('#downloadReportPng').disabled=true;setFormError(document.querySelector('#reportForm'));document.querySelector('#reportDialog').showModal()};
document.querySelector('#reportRange').onchange=event=>{document.querySelector('#reportCustomDates').hidden=event.target.value!=='custom'};document.querySelector('#reportDialog').addEventListener('close',()=>{const canvas=document.querySelector('#reportCanvas');canvas.width=0;canvas.height=0;document.querySelector('#reportPreview').hidden=true;document.querySelector('#downloadReportPng').disabled=true});
document.querySelector('#reportForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=event.submitter||document.querySelector('#generateReportBtn');setFormError(form);if(button)button.disabled=true;document.querySelector('#downloadReportPng').disabled=true;document.querySelector('#reportPreview').hidden=true;try{const range=form.elements.range.value,end=new Date(),start=new Date(end);if(range==='24h')start.setHours(start.getHours()-24);else if(range==='7d')start.setDate(start.getDate()-7);else if(range==='30d')start.setDate(start.getDate()-30);else{const customStart=new Date(form.elements.start.value),customEnd=new Date(form.elements.end.value);if(!form.elements.start.value||!form.elements.end.value||!Number.isFinite(customStart.getTime())||!Number.isFinite(customEnd.getTime())||customStart>=customEnd)throw new Error('Choose a valid start and end date/time.');start.setTime(customStart.getTime());end.setTime(customEnd.getTime())}const metrics=[...form.querySelectorAll('input[name=\"metric\"]:checked')].map(input=>input.value);if(!metrics.length)throw new Error('Select at least one metric to chart.');const query=new URLSearchParams({start:String(start.getTime()/1000),end:String(end.getTime()/1000),device_id:form.elements.device_id.value}),report=await api('/report?'+query.toString()),selection=form.elements.device_id.value,deviceLabel=selection==='all'?'All devices':document.querySelector('#reportDevice').selectedOptions[0]?.textContent||'Selected device';renderReportChart(report,metrics,start.getTime(),end.getTime(),deviceLabel);document.querySelector('#reportPreview').hidden=false;document.querySelector('#downloadReportPng').disabled=false}catch(error){setFormError(form,error.message||'Could not generate the chart.')}finally{if(button)button.disabled=false}};
document.querySelector('#downloadReportPng').onclick=()=>{const canvas=document.querySelector('#reportCanvas'),anchor=document.createElement('a'),name=(document.querySelector('#reportDevice').selectedOptions[0]?.textContent||'all-devices').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'device-report';anchor.download=`ariyou-report-${name}-${new Date().toISOString().slice(0,10)}.png`;if(canvas.toBlob)canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);anchor.href=url;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png');else{anchor.href=canvas.toDataURL('image/png');anchor.click()}};
